SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[tableName] COLLATE DATABASE_DEFAULT AS [tableName],[name] COLLATE DATABASE_DEFAULT AS [name],[typeName] COLLATE DATABASE_DEFAULT AS [typeName],[collation_name] COLLATE DATABASE_DEFAULT AS [collation_name],[identitySeed] COLLATE DATABASE_DEFAULT AS [identitySeed],[identityIncrement] COLLATE DATABASE_DEFAULT AS [identityIncrement],[computedDefinition] COLLATE DATABASE_DEFAULT AS [computedDefinition],[defaultName] COLLATE DATABASE_DEFAULT AS [defaultName],[defaultDefinition] COLLATE DATABASE_DEFAULT AS [defaultDefinition],[column_id],[max_length],[precision],[scale],[is_nullable],[is_identity],[is_computed],[is_persisted] INTO #Expected_columns FROM OPENJSON(@expected) WITH ([schemaName] nvarchar(4000) '$.schemaName',[tableName] nvarchar(4000) '$.tableName',[name] nvarchar(4000) '$.name',[typeName] nvarchar(4000) '$.typeName',[collation_name] nvarchar(4000) '$.collation_name',[identitySeed] nvarchar(4000) '$.identitySeed',[identityIncrement] nvarchar(4000) '$.identityIncrement',[computedDefinition] nvarchar(4000) '$.computedDefinition',[defaultName] nvarchar(4000) '$.defaultName',[defaultDefinition] nvarchar(4000) '$.defaultDefinition',[column_id] int '$.column_id',[max_length] int '$.max_length',[precision] int '$.precision',[scale] int '$.scale',[is_nullable] bit '$.is_nullable',[is_identity] bit '$.is_identity',[is_computed] bit '$.is_computed',[is_persisted] bit '$.is_persisted');
SELECT [schemaName] COLLATE DATABASE_DEFAULT AS [schemaName],[tableName] COLLATE DATABASE_DEFAULT AS [tableName],[name] COLLATE DATABASE_DEFAULT AS [name],[typeName] COLLATE DATABASE_DEFAULT AS [typeName],[collation_name] COLLATE DATABASE_DEFAULT AS [collation_name],[identitySeed] COLLATE DATABASE_DEFAULT AS [identitySeed],[identityIncrement] COLLATE DATABASE_DEFAULT AS [identityIncrement],[computedDefinition] COLLATE DATABASE_DEFAULT AS [computedDefinition],[defaultName] COLLATE DATABASE_DEFAULT AS [defaultName],[defaultDefinition] COLLATE DATABASE_DEFAULT AS [defaultDefinition],[column_id],[max_length],[precision],[scale],[is_nullable],[is_identity],[is_computed],[is_persisted] INTO #Actual_columns FROM (SELECT SCHEMA_NAME(t.schema_id) schemaName,t.name tableName,c.column_id,c.name,ty.name typeName,c.max_length,c.precision,c.scale,c.is_nullable,c.is_identity,c.is_computed,c.collation_name,CONVERT(varchar(40),ic.seed_value) identitySeed,CONVERT(varchar(40),ic.increment_value) identityIncrement,cc.definition computedDefinition,cc.is_persisted,dc.name defaultName,dc.definition defaultDefinition FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id JOIN sys.types ty ON ty.user_type_id=c.user_type_id LEFT JOIN sys.identity_columns ic ON ic.object_id=c.object_id AND ic.column_id=c.column_id LEFT JOIN sys.computed_columns cc ON cc.object_id=c.object_id AND cc.column_id=c.column_id LEFT JOIN sys.default_constraints dc ON dc.object_id=c.default_object_id) actual;
