BEGIN
 SELECT 'Missing or changed' AS Difference,* FROM (SELECT * FROM #Expected_columns EXCEPT SELECT * FROM #Actual_columns) missing;
 SELECT 'Unexpected or changed' AS Difference,* FROM (SELECT * FROM #Actual_columns EXCEPT SELECT * FROM #Expected_columns) extra;
 THROW 51001, 'Verify columns failed.', 1;
END;
DROP TABLE #Expected_columns; DROP TABLE #Actual_columns;
PRINT 'PASS columns';
GO
